<template><view class='page'><AppNavBar title='手动创建吉他谱' show-back /><view class='container'><input v-model='form.title' class='input' placeholder='歌名'/><input v-model='form.artist_name' class='input' placeholder='歌手'/><input v-model='form.song_key' class='input' placeholder='调式(C/G/Am)'/><textarea v-model='form.raw_text' class='textarea' placeholder='输入吉他谱内容'></textarea><view class='btn' @tap='submit'>保存曲谱</view></view></view></template><script setup lang='ts'>import {reactive} from 'vue';import AppNavBar from '../../components/AppNavBar.vue';import {createManualSong} from '../../api/manualSong';const form=reactive({title:'',artist_name:'',song_key:'C',raw_text:''});async function submit(){const song=await createManualSong(form);uni.navigateTo({url:'/pages/song-detail/index?id='+song.id})}</script><style scoped>.page{min-height:100vh;background:#fafaf6}.input,.textarea{margin-top:20rpx;background:#fff;padding:30rpx;border-radius:24rpx}.textarea{height:500rpx}.btn{margin-top:40rpx;height:88rpx;border-radius:44rpx;background:#1e7a5a;color:#fff;display:flex;align-items:center;justify-content:center}</style>